#include <bits/stdc++.h>
using namespace std;
#define MAXN 15000
struct Edge {
    int to, capacity, flow, cost;
};
vector<Edge> graph_edges;
vector<int> adjacency[MAXN];
long long total_flow_cost, distance[MAXN];
int total_nodes, total_edges, rebels, cost_param, delay, p[MAXN], pe[MAXN], inq[MAXN], source=9998, sink=9999, current_node, i, j;
void create_edge(int from, int to, int cap, int cst) {
    adjacency[from].push_back(graph_edges.size()); graph_edges.push_back({to, cap, 0, cst});
    adjacency[to].push_back(graph_edges.size()); graph_edges.push_back({from, 0, 0, -cst});
}
void dispatch_rebels() {
    fill(distance, distance + 10000, (long long)1e18);
    fill(p, p + 10000, -1);
    fill(pe, pe + 10000, -1);
    fill(inq, inq + 10000, 0);
    distance[source] = 0;
    queue<int> q;
    q.push(source);
    inq[source] = 1;
    current_node = sink;
    while (!q.empty()) {
        int node = q.front(); q.pop();
        inq[node] = 0;
        for (auto e_idx : adjacency[node]) {
            if (graph_edges[e_idx].capacity - graph_edges[e_idx].flow == 0) continue;
            int cst = graph_edges[e_idx].cost, y = graph_edges[e_idx].to;
            if (distance[y] > distance[node] + cst) {
                distance[y] = distance[node] + cst;
                p[y] = node;
                pe[y] = e_idx;
                if (!inq[y]) { inq[y] = 1; q.push(y); }
            }
        }
    }
    int node_ptr = current_node;
    while (node_ptr != source) {
        graph_edges[pe[node_ptr]].flow++;
        graph_edges[pe[node_ptr] ^ 1].flow--;
        node_ptr = p[node_ptr];
    }
    total_flow_cost += distance[sink];
}
int main() {
    cin >> total_nodes >> total_edges >> rebels >> cost_param >> delay;
    int x, y;
    for (int i = 1; i <= rebels; i++) { cin >> x; x--; create_edge(source, x, 1, 0); }
    for (int i = 1; i <= 101; i++) create_edge((i - 1) * total_nodes, sink, rebels, (i - 1) * cost_param);
    for (int i = 1; i <= total_edges; i++) {
        cin >> x >> y; x--; y--;
        for (int i = 1; i <= 100; i++) {
            for (int j = 1; j <= rebels; j++) {
                create_edge(x + (i - 1) * total_nodes, y + (i - 1) * total_nodes + total_nodes, 1, delay * ((j - 1) * 2 + 1));
                create_edge(y + (i - 1) * total_nodes, x + (i - 1) * total_nodes + total_nodes, 1, delay * ((j - 1) * 2 + 1));
            }
        }
    }
    for (int i = 1; i <= total_nodes; i++) {
        for (int j = 1; j <= 100; j++) {
            create_edge(i - 1 + (j - 1) * total_nodes, i - 1 + (j - 1) * total_nodes + total_nodes, rebels, 0);
        }
    }
    for (int i = 1; i <= rebels; i++) dispatch_rebels();
    cout << total_flow_cost << endl;
    return 0;
}
